theme.customCSS:
/* Voile des héros plein écran. Le repli générique de shared.css:86 est un noir à
   45 % : correct, mais neutre. On pose ici la teinte VERTE du site, pour que le
   voile appartienne à l'identité plutôt que d'être un simple assombrissement. */
:root { --hero-tint: oklch(0.22 0.025 150 / 0.45); }
.dark { --hero-tint: oklch(0.14 0.02 150 / 0.55); }
